def largest(a, b, c):
    big = a
    if b > big:
        big = b
    if c > big:
        big = c
    return big

def fact(n):
    r = 1
    for i in range(1, n + 1):
        r *= i
    return r

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

print(largest(4, 19, 7), fact(5), is_prime(13), is_prime(15))
